 for(let i=0;i<model.anchors.length;i++){const a=model.anchors[i],q=p(...a.point),label=document.createElement('div');label.className='scene-label';label.innerHTML=`<small>${String(i+1).padStart(2,'0')}</small>${safe(a.label)}`;labelLayer.append(label);labels.push({label,p:q.clone().add(p(0,.75,0))});if(gpu){const stem=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,.5,6),new THREE.MeshBasicMaterial({color:'#d9d3af'}));stem.position.copy(q).add(p(0,.25,0));group.add(stem);const head=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),new THREE.MeshBasicMaterial({color:i===0?'#edac78':'#cfbd91'}));head.position.copy(q).add(p(0,.55,0));group.add(head)}else meshItems.push({type:'marker',points:[q],color:new THREE.Color(i===0?'#edac78':'#cfbd91'),layer:4})}
